local config = {
  ui_story_5067_50670101_1_dialog_content = "Hiks-hiks... Connolly...",
  ui_story_5067_50670101_2_dialog_content = "Eh? Anton?",
  ui_story_5067_50670101_3_dialog_content = "Seperti Aqua Lord di masa lalu, aku masih merasa takut saat tiba-tiba muncul...",
  ui_story_5067_50670101_4_dialog_content = "Tunggu... apakah itu menangis? T-Tapi, kenapa...?",
  ui_story_5067_50670101_5_dialog_content = "Kami... Kami merindukan rumah kami...",
  ui_story_5067_50670101_6_dialog_content = "Temple kami yang indah hancur...",
  ui_story_5067_50670101_7_dialog_content = "Ini tak tertahankan.",
  ui_story_5067_50670101_8_dialog_content = "Jadi, kamu marah karena kehilangan candi kamu...",
  ui_story_5067_50670101_9_dialog_content = "Benar, serangan Raja Merman membuatnya rusak parah hingga tak bisa dikenali...",
  ui_story_5067_50670101_10_dialog_content = "Aku begitu sibuk membantu semua orang membangun kembali kota ini sampai-sampai aku melupakan itu semua...",
  ui_story_5067_50670101_11_dialog_content = "Boo-hoo... Kami hanya ingin lari dari tempat ini...",
  ui_story_5067_50670101_12_dialog_content = "Dulu, kehadiran kita saja membuat semua orang tunduk dalam penyembahan.",
  ui_story_5067_50670101_13_dialog_content = "Tapi tak ada yang memperhatikan kita lagi. Kita sudah dilupakan...",
  ui_story_5067_50670101_14_dialog_content = "Umm... Jangan membuat diri kalian terdengar begitu tak berarti...",
  ui_story_5067_50670101_15_dialog_content = "I-Ini pasti semua hanya sementara!",
  ui_story_5067_50670101_16_dialog_content = "Kota ini baru saja mengalami banyak hal... Semua orang hanya butuh waktu untuk menyembuhkan diri saat ini...",
  ui_story_5067_50670101_17_dialog_content = "Sebagian besar penduduk kota berjuang hanya untuk memenuhi kebutuhan dasar mereka...",
  ui_story_5067_50670101_18_dialog_content = "Jika kita bisa membantu mereka membangun kembali rumah mereka dan mengembalikan ketertiban di kota ini...",
  ui_story_5067_50670101_19_dialog_content = "Saya yakin lebih banyak lagi dari mereka yang akan membantu kita membangun kembali kuil Anda!",
  ui_story_5067_50670101_20_dialog_content = "Benarkah? Kita akan membangunnya lagi?!",
  ui_story_5067_50670101_21_dialog_content = "Tentu saja. Aku berjanji kita akan membuat rumah baru untukmu.",
  ui_story_5067_50670101_22_dialog_content = "Kami percaya padamu, Connolly.",
  ui_story_5067_50670101_23_dialog_content = "Jadi, uh... Kalian bertiga punya ide bagaimana cara membangun ulangnya...?",
  ui_story_5067_50670101_24_dialog_content = "Ini harus sempurna! Sebuah candi utama yang lebih hebat daripada candi-candi sebelumnya!",
  ui_story_5067_50670101_25_dialog_content = "Kita harus tidak menghemat biaya untuk membuatnya seagung mungkin.",
  ui_story_5067_50670101_26_dialog_content = "Aku hanya ingin... tempat yang bisa kusebut rumah.",
  ui_story_5067_50670101_27_dialog_content = "Tahu tidak... Aku rasa Aqua Lord juga pernah mengatakan sesuatu yang mirip di masa lalu...",
  ui_story_5067_50670101_28_dialog_content = "Tapi pertanyaan sebenarnya adalah, bagaimana saya akan menjelaskan tuntutan ini kepada warga kota?",
  ui_story_5067_50670101_29_dialog_content = "Bisakah semua orang mengingat seperti apa kuil itu...",
  ui_story_5067_50670101_30_dialog_content = "... ketika kamu disembah sebagai Aqua Lord?",
  ui_story_5067_50670101_31_dialog_content = "Kamu adalah Aqua Queen, bukan Connolly? Kamu pikirkan sesuatu!",
  ui_story_5067_50670101_32_dialog_content = "Apa yang pernah ada di masa lalu mungkin tidak berlaku di masa kini.",
  ui_story_5067_50670101_33_dialog_content = "Sebenarnya, aku tidak begitu ingat.",
  ui_story_5067_50670101_34_dialog_content = "Oh... Saya kira Anda benar...",
  ui_story_5067_50670101_35_dialog_content = "(Anton-anton kehilangan sebagian besar ingatan mereka...)",
  ui_story_5067_50670101_36_dialog_content = "(Meskipun aku mewarisi kekuatan Aqua Lord... Aku tidak memiliki kesempatan untuk mempelajari masa lalunya atau tradisinya.)",
  ui_story_5067_50670101_37_dialog_content = "Tidak apa-apa jika kamu tidak ingat semuanya... Jika kamu bisa memberi beberapa ide kecil, saya bisa bekerja dengan itu.",
  ui_story_5067_50670101_38_dialog_content = "Dulu kami sering menerima banyak tawaran makanan lezat dan berair!",
  ui_story_5067_50670101_39_dialog_content = "(Jadi ada mesin kudapan tak terbatas di ruangan itu?)",
  ui_story_5067_50670101_40_dialog_content = "Sebuah aula batu yang megah, di mana cahaya dan bayangan saling berkelindan... Bentuk kami yang kuat diterangi dalam cahaya lilin.",
  ui_story_5067_50670101_41_dialog_content = "(Tampaknya harus menjadi kuil yang besar... Mungkin dengan banyak kaca dan lampu gantung.)",
  ui_story_5067_50670101_42_dialog_content = "Sangat besar. Kalau tidak, kami tidak akan menyukainya.",
  ui_story_5067_50670101_43_dialog_content = "Fiuh... Baiklah, itu membuat semuanya sedikit lebih jelas...",
  ui_story_5067_50670101_44_dialog_content = "Serahkan saja padaku...!",
  ui_story_5067_50670101_45_dialog_content = "Aku akan memastikan semua orang tahu persis bagaimana kau ingin kuil barumu dibangun.",
  ui_story_5067_50670101_46_dialog_content = "Terima kasih, Connolly!",
  ui_story_5067_50670301_1_dialog_content = "Queen Connolly! Saya memiliki urusan penting untuk dibahas dengan kamu!",
  ui_story_5067_50670301_2_dialog_content = "Meskipun jadwal yang sibuk, kita tidak boleh meremehkan hal ini.",
  ui_story_5067_50670301_3_dialog_content = "... Oke! Aku akan berusaha sebaik mungkin untuk mendengarkan!",
  ui_story_5067_50670301_4_dialog_content = "Ah... Aku hanya berharap kamu masih bisa berbicara denganku seperti dulu. Rasanya sedikit aneh sekarang.",
  ui_story_5067_50670301_5_dialog_content = "Aku bisa mendengarmu, tapi itu perintah yang aku tolak untuk melaksanakan!",
  ui_story_5067_50670301_6_dialog_content = "Mempertahankan martabat teman-teman adalah sesuatu yang selalu aku lakukan.",
  ui_story_5067_50670301_7_dialog_content = "Begitu... Mari kita kembali membahas masalah kota ini, ya?",
  ui_story_5067_50670301_8_dialog_content = "Ya, Queen Connolly!",
  ui_story_5067_50670301_9_dialog_content = "Pertama, masih ada sejumlah prajurit merman berkeliaran di dekat kota. Saya sedang menyusun tim pengintai untuk membantu saya menyingkirkan mereka.",
  ui_story_5067_50670301_10_dialog_content = "Membasmi mereka sepenuhnya terbukti menjadi tugas yang sangat sulit.",
  ui_story_5067_50670301_11_dialog_content = "Oh.. Itu memang terdengar cukup frustrasi... Tapi mungkin tentakelku bisa membantu kamu dalam pertempuran?",
  ui_story_5067_50670301_12_dialog_content = "Tidak, Robyn dan aku bisa menangani ini dengan baik sendiri. Yang lebih penting...",
  ui_story_5067_50670301_13_dialog_content = "Banyak warga kota melaporkan halusinasi aneh, dan kami membutuhkan bantuanmu untuk itu!",
  ui_story_5067_50670301_14_dialog_content = "Tunggu, apa...?",
  ui_story_5067_50670301_15_dialog_content = "Beberapa hal aneh terjadi di kota akhir-akhir ini, dan banyak orang mengaku melihat dan mendengar hal-hal aneh juga.",
  ui_story_5067_50670301_16_dialog_content = "Halusinasi... Jadi mereka melihat dan mendengar hal-hal yang sebenarnya tidak ada...?",
  ui_story_5067_50670301_17_dialog_content = "Tepat sekali, ini aneh. Mereka mulai berdebat tentang harta tak terlihat dan kejadian yang tidak pernah terjadi.",
  ui_story_5067_50670301_18_dialog_content = "Beberapa bahkan sampai menggunakan kekerasan.",
  ui_story_5067_50670301_19_dialog_content = "Bagaimana hal seperti ini bisa terjadi...?",
  ui_story_5067_50670301_20_dialog_content = "Kami masih dalam proses membangun kembali... Jika ini terus terjadi, semuanya akan hancur lagi.",
  ui_story_5067_50670301_21_dialog_content = "Dan kemudian janjiku pada Anton dan semua orang lainnya akan...",
  ui_story_5067_50670301_22_dialog_content = "Andai saja Aqua Lord ada di sini untuk membimbingku...",
  ui_story_5067_50670301_23_dialog_content = "Tidak, ini adalah tanggung jawabku untuk dipikul! Saya harus menemukan jawaban sendiri!",
  ui_story_5067_50670301_24_dialog_content = "Sepertinya kamu juga kehabisan ide, ya?",
  ui_story_5067_50670301_25_dialog_content = "Lumba-lumba Putih mengatakan bahwa beberapa penduduk kota juga sangat berpengetahuan...",
  ui_story_5067_50670301_26_dialog_content = "Mungkin salah satu dari mereka bisa membantu saya menyelesaikan masalah ini... Apakah kamu tahu ada orang seperti itu?",
  ui_story_5067_50670301_27_dialog_content = "Seseorang yang berpengetahuan... Sepertinya aku tahu seseorang yang cocok untuk itu...",
  ui_story_5067_50670301_28_dialog_content = "Seorang bijak yang pernah mengikuti pahlawan legendaris Istvan. Dia dikenal sebagai—Wanita dalam Teko!",
  ui_story_5067_50670301_29_dialog_content = "Konon, dia sangat kaya raya dan hidup menyendiri di sebuah rumah besar rahasia di mana ada perahu yang bersandar di laut.",
  ui_story_5067_50670301_30_dialog_content = "Dengan kebijaksanaannya, dia mungkin bisa mengarahkan kamu ke arah yang benar.",
  ui_story_5067_50670301_31_dialog_content = "Terima kasih... Terima kasih banyak, Dayna. Aku akan memikirkan cara untuk menemukan sage ini...",
  ui_story_5067_50670301_32_dialog_content = "Nyonya di dalam Teko... Benar?",
  ui_story_5067_50670301_33_dialog_content = "Ayo pergi sekarang!",
  ui_story_5067_50670301_34_dialog_content = "Kamu bisa menggunakan penasihat kerajaan, Connolly.",
  ui_story_5067_50670301_35_dialog_content = "Menyelesaikan masalah akan jauh lebih mudah dengan satu.",
  ui_story_5067_50670301_36_dialog_content = "Aku... Aku tahu. Aku hanya perlu mengumpulkan keberanian... untuk meminta dia menjadi pembimbingku!",
  ui_story_5067_50670501_1_dialog_content = "Ini... Ini tempatnya...?",
  ui_story_5067_50670501_2_dialog_content = "Um... Maafkan saya, tetapi apakah Lady di dalam Teko tersedia sekarang...?",
  ui_story_5067_50670501_3_dialog_content = "Nah nah, kalau bukan Connolly... Ratu baru di kota ini.",
  ui_story_5067_50670501_4_dialog_content = "Biarkan aku menebak, kamu menemui masalah dan membutuhkan nasihat dariku?",
  ui_story_5067_50670501_5_dialog_content = "Hah...? B-Bagaimana kamu tahu...?",
  ui_story_5067_50670501_6_dialog_content = "Tak ada yang terjadi di dasar laut yang luput dari pengetahuanku. Mari kita lihat saja...",
  ui_story_5067_50670501_7_dialog_content = "Jika permintaan Anda layak untuk dipertimbangkan!",
  ui_story_5067_50670501_8_dialog_content = "Nah... Orang-orang di kota ini belakangan ini sering melihat dan mendengar hal-hal aneh...",
  ui_story_5067_50670501_9_dialog_content = "Aku ingin tahu apakah kamu bisa memberitahu penyebab halusinasi ini!",
  ui_story_5067_50670501_10_dialog_content = "Sebagai ratu, aku harus mencari cara untuk menyingkirkan mereka...",
  ui_story_5067_50670501_11_dialog_content = "Kalau tidak, usaha rekonstruksi kita akan sia-sia, dan seluruh kota akan kembali terjerumus ke dalam kekacauan!",
  ui_story_5067_50670501_12_dialog_content = "Cerita di balik masalah ini panjang dan rumit, dan juga erat kaitannya dengan kamu.",
  ui_story_5067_50670501_13_dialog_content = "Tentu kamu tahu sejarah Aqua Lord, kan?",
  ui_story_5067_50670501_14_dialog_content = "Uh... Y-Ya, Aqua Lord sudah tidak aktif untuk waktu yang sangat lama, dan benar-benar tidak menyebutkan masa lalunya kepada saya.",
  ui_story_5067_50670501_15_dialog_content = "Heheh, jadi kamu sama sekali tidak menyadari. Tahukah kamu bahwa Aqua Lord pernah dikenal sebagai dewa ketakutan dan penderitaan?",
  ui_story_5067_50670501_16_dialog_content = "Takut... dan sakit?!",
  ui_story_5067_50670501_17_dialog_content = "Memang. Wajah mengerikan Aqua Lord membuat orang lain patuh karena ketakutan, dan kekuatan mutlaknya membawa penderitaan yang tak tertahankan bagi semua yang melanggar wilayahnya.",
  ui_story_5067_50670501_18_dialog_content = "Aqua Lord adalah dewa yang benar-benar berbahaya pada masanya.",
  ui_story_5067_50670501_19_dialog_content = "...",
  ui_story_5067_50670501_20_dialog_content = "Tapi... Tapi saya tidak pernah berpikir itu semua begitu menakutkan...",
  ui_story_5067_50670501_21_dialog_content = "Oho? Mungkin kamu benar. Bagaimanapun juga, seorang dewa tidak memilih tujuannya sendiri.",
  ui_story_5067_50670501_22_dialog_content = "Namun, kematian dan kelahiran kembali-nya pasti menghasilkan banyak fragmen kekuatan.",
  ui_story_5067_50670501_23_dialog_content = "Situasi saat ini tidak ada bedanya.",
  ui_story_5067_50670501_24_dialog_content = "Kemungkinan besar sumber halusinasi pada penduduk kota dan prajurit ikan duyung adalah kekuatan yang sama.",
  ui_story_5067_50670501_25_dialog_content = "Meskipun mereka hanya fragmen dari kekuatan asli Aqua Lord, mereka sudah memberikan dampak yang sangat signifikan pada kota.",
  ui_story_5067_50670501_26_dialog_content = "Jika ini memang kasusnya, apakah Anda benar-benar berniat untuk menyelesaikan dilema ini secara pribadi?",
  ui_story_5067_50670501_27_dialog_content = "Tentu saja. Ini adalah kewajiban saya untuk menyelesaikannya sebagai Ratu.",
  ui_story_5067_50670501_28_dialog_content = "Saya hanya tidak tahu bagaimana potongan-potongan kekuatan ini akan mempengaruhi Antons...",
  ui_story_5067_50670501_29_dialog_content = "Oh... Kau khawatir tentang benda kecil itu?",
  ui_story_5067_50670501_30_dialog_content = "Sangat wajar jika Anda menginginkan fragmen kekuatan Aqua Lord untuk diri sendiri...",
  ui_story_5067_50670501_31_dialog_content = "Merekonstruksi kuil keyakinan seharusnya cukup mudah dengan kekuatan seperti itu.",
  ui_story_5067_50670501_32_dialog_content = "Sangat baik jika bisa memberikan mereka rumah baru sesegera mungkin... tapi...",
  ui_story_5067_50670501_33_dialog_content = "Kamu khawatir bahwa membangun kembali kuil mereka akan mengembalikan kekuatan asli mereka... bukan?",
  ui_story_5067_50670501_34_dialog_content = "... Kau takut bahwa mereka akan menjadi simbol ketakutan dan penderitaan sekali lagi...",
  ui_story_5067_50670501_35_dialog_content = "Yah... Anu...",
  ui_story_5067_50670501_36_dialog_content = "Kamu terlihat sangat imut saat khawatir...",
  ui_story_5067_50670501_37_dialog_content = "Tapi jangan khawatir, sayangku. Kamu tidak perlu takut sedikit pun.",
  ui_story_5067_50670501_38_dialog_content = "Saat anak-anak kecil itu perlahan mendapatkan kembali kekuatan mereka sebelumnya, apakah mereka akan naik ke takhta teror...",
  ui_story_5067_50670501_39_dialog_content = "Atau menjadi sesuatu yang sepenuhnya berbeda...",
  ui_story_5067_50670501_40_dialog_content = "Semua tergantung pada pikiranmu, Connolly. Bagaimanapun, hanya kamu yang bisa mengontrolnya.",
  ui_story_5067_50670501_41_dialog_content = "Pikiran... saya...?",
  ui_story_5067_50670501_42_dialog_content = "Saya mengerti. Aku... Aku akan melakukan apa yang kupikir benar.",
  ui_story_5067_50670501_43_dialog_content = "Mereka adalah teman pentingku, sekaligus pelindung kota ini. Aku... Aku tidak seharusnya meragukan mereka seperti ini.",
  ui_story_5067_50670501_44_dialog_content = "Sangat baik. Sekarang lakukan apa yang kamu rasa benar, dan lakukan dengan keyakinan. Aku lebih dari senang untuk terus memberikan saran jika dibutuhkan.",
  ui_story_5067_50670501_45_dialog_content = "Untuk pembayaranku... Heheh, jangan khawatir sayang, aku pasti akan memberimu penawaran yang baik.",
  ui_story_5067_50670601_1_dialog_content = "Fiuh... Sudah lama kita tidak mendapatkan laporan tentang halusinasi...",
  ui_story_5067_50670601_2_dialog_content = "Sekarang kota ini kembali damai, saya jadi penasaran bagaimana rekonstruksi kuil itu berjalan...?",
  ui_story_5067_50670601_3_dialog_content = "Lihat, ini Queen Connolly!",
  ui_story_5067_50670601_4_dialog_content = "Kota kami jauh lebih aman karena perlindungan Anda! Hidup sang Ratu!",
  ui_story_5067_50670601_5_dialog_content = "Hidup panjang Queen Connolly, yang menyelamatkan kita dari kenangan menyakitkan!",
  ui_story_5067_50670601_6_dialog_content = "Tanpa intervensi baik hatinya, siapa tahu berapa lama kita akan diganggu oleh halusinasi-halusinasi itu...",
  ui_story_5067_50670601_7_dialog_content = "Tunggu... Tunggu!",
  ui_story_5067_50670601_8_dialog_content = "Kalian lagi! Apa yang kalian inginkan dari Ratu kami kali ini?!",
  ui_story_5067_50670601_9_dialog_content = "Jangan salah paham! K-Kami datang untuk menawarkan Queen Connolly rasa terima kasih kami juga!",
  ui_story_5067_50670601_10_dialog_content = "Meskipun kami selalu mencoba menangkapnya di masa lalu, dia masih merasa perlu untuk membebaskan kami dari halusinasi mimpi buruk itu....",
  ui_story_5067_50670601_11_dialog_content = "Yang Mulia! Jika Anda tidak keberatan, kami juga ingin menawarkan bantuan kami!",
  ui_story_5067_50670601_12_dialog_content = "Jika kamu benar-benar ingin membantu...",
  ui_story_5067_50670601_13_dialog_content = "Baiklah! Kami benar-benar membutuhkan beberapa tangan tambahan untuk menyelesaikan rekonstruksi kuil, jadi pergilah ke sana dan lihat apa yang mereka butuhkan!",
  ui_story_5067_50670601_14_dialog_content = "Seperti yang Anda inginkan, Queen Connolly!",
  ui_story_5067_50670601_15_dialog_content = "Transisi",
  ui_story_5067_50670601_16_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian—</color>",
  ui_story_5067_50670601_17_dialog_content = "Dengan ini saya nyatakan bahwa pembangunan kuil Queen Connolly... telah selesai secara resmi!",
  ui_story_5067_50670601_18_dialog_content = "Hidup sang Ratu! Hidup sang Ratu!",
  ui_story_5067_50670601_19_dialog_content = "Kini Aqua Queen memiliki kuil baru, kota kita dapat menikmati kedamaian yang langgeng kembali!",
  ui_story_5067_50670601_20_dialog_content = "Terima kasih kepada Ratu, kami bisa membangun kembali rumah kami.",
  ui_story_5067_50670601_21_dialog_content = "Lihat! Apakah itu dia...?",
  ui_story_5067_50670601_22_dialog_content = "Connolly! Connolly! Connolly!",
  ui_story_5067_50670601_23_dialog_content = "Ahhhhh... It-Itu cukup, semua orang! Kamu membuatku malu...",
  ui_story_5067_50670601_24_dialog_content = "Fiuh, akhirnya aku bisa kabur. Meskipun tidak terlalu menggangguku, semua orang masih terlalu bersemangat...",
  ui_story_5067_50670601_25_dialog_content = "Tapi, yang lebih penting…",
  ui_story_5067_50670601_26_dialog_content = "Rumah kita! Rumah kuil baru kita! Hmm-hmm-hmm!",
  ui_story_5067_50670601_27_dialog_content = "Selama ini, para Anton sama sekali tidak merasa tenang sedikit pun...",
  ui_story_5067_50670601_28_dialog_content = "Mereka pasti sangat senang... Apa kalian suka rumah baru kalian, teman-teman?",
  ui_story_5067_50670601_29_dialog_content = "Sempurna, Connolly! Kami sangat mencintaimu!",
  ui_story_5067_50670601_30_dialog_content = "Lebih menakjubkan dari yang kami bayangkan. Terima kasih.",
  ui_story_5067_50670601_31_dialog_content = "Ingatan kita perlahan kembali.",
  ui_story_5067_50670601_32_dialog_content = "Hah? Maksudmu... Kamu mulai mengingat masa lalumu?",
  ui_story_5067_50670601_33_dialog_content = "Ya, dan banyak sekali!",
  ui_story_5067_50670601_34_dialog_content = "Ketuhanan kita sedang kembali kepada kita saat ini juga.",
  ui_story_5067_50670601_35_dialog_content = "Bobot kekuatan dan tujuan kita.",
  ui_story_5067_50670601_36_dialog_content = "Apa?! Maksudku... Apakah begitu? Aku sangat senang untuk kalian bertiga...",
  ui_story_5067_50670601_37_dialog_content = "(Tapi menurut Lady di dalam Teko...)",
  ui_story_5067_50670601_38_dialog_content = "(Apakah ini berarti dewa ketakutan dan penderitaan akan terlahir kembali?)",
  ui_story_5067_50670601_39_dialog_content = "Kalau sampai itu terjadi...",
  ui_story_5067_50670601_40_dialog_content = "Tidak, saya percaya dewa baru akan datang untuk tinggal di kuil indah yang baru ini.",
  ui_story_5067_50670601_41_dialog_content = "Hah? Suara itu...",
  ui_story_5067_50670601_42_dialog_content = "Dan dewa ini akan memiliki nama baru, yang penuh dengan kebaikan dan kebahagiaan.",
  ui_story_5067_50670601_43_dialog_content = "Mungkin itu akan menjadi... Dewa musik dan persahabatan?",
  ui_story_5067_50670601_44_dialog_content = "Kau rupanya... si Lumba-lumba Putih...",
  ui_story_5067_50670601_45_dialog_content = "Tunggu aku! Saya datang untuk menemukanmu!",
  ui_story_5067_50670801_1_dialog_content = "Haa... Haa... Lumba-lumba Putih... Aku kira...",
  ui_story_5067_50670801_2_dialog_content = "Kupikir aku takkan pernah mendengar kabar darimu lagi.",
  ui_story_5067_50670801_3_dialog_content = "Jangan khawatir. Aku selalu ada di sampingmu.",
  ui_story_5067_50670801_4_dialog_content = "Tapi setelah melihat betapa baiknya Anda selama ini, saya pikir ini adalah yang terbaik.",
  ui_story_5067_50670801_5_dialog_content = "Kamu pikir aku... Melakukan dengan baik?",
  ui_story_5067_50670801_6_dialog_content = "Tentu saja. Dan sekarang, kamu dan para Anton telah menguasai kekuatan dewa baru.",
  ui_story_5067_50670801_7_dialog_content = "Hah...?!",
  ui_story_5067_50670801_8_dialog_content = "Lihat saja... Kamu bisa melihat ikan di setiap jalan di kota ini sekarang, bukan?",
  ui_story_5067_50670801_9_dialog_content = "Sebenarnya, kamu bahkan seharusnya bisa melihat dunia luar—",
  ui_story_5067_50670801_10_dialog_content = "I-Ini luar biasa! Rasanya seperti mimpi!",
  ui_story_5067_50670801_11_dialog_content = "Bisakah sebenarnya aku sedang bermimpi sekarang?",
  ui_story_5067_50670801_12_dialog_content = "Oh? Akhirnya kamu menyadarinya juga?",
  ui_story_5067_50670801_13_dialog_content = "Hah...? Aku tahu itu...",
  ui_story_5067_50670801_14_dialog_content = "Tapi ini bukan mimpi biasa, Connolly.",
  ui_story_5067_50670801_15_dialog_content = "Ketakutan dan rasa sakit yang pernah diwujudkan oleh Aqua Lord sebenarnya adalah sumber kekuatan terpendam Anda.",
  ui_story_5067_50670801_16_dialog_content = "Di masa lalu, Anda mengembangkan kekuatan untuk terhubung dengan kehampaan agar dapat menghindari rasa sakit dan mengatasi ketakutan Anda.",
  ui_story_5067_50670801_17_dialog_content = "Masa laluku... Aku mengerti...",
  ui_story_5067_50670801_18_dialog_content = "Dulu, ada banyak ketakutan dan rasa sakit yang ingin saya hindari...",
  ui_story_5067_50670801_19_dialog_content = "Tapi setelah semua cobaan dan kesulitan yang kau alami, kau akhirnya menyadari sesuatu, 'kan?",
  ui_story_5067_50670801_20_dialog_content = "Pentingnya memiliki teman dan tempat yang bisa disebut rumah, serta kepercayaan dan kebaikan dari orang lain.",
  ui_story_5067_50670801_21_dialog_content = "Menjadi dewa baru berarti kamu tidak perlu lagi bersembunyi dari rasa takut atau sakit di balik topeng.",
  ui_story_5067_50670801_22_dialog_content = "Musik dan persahabatan: inilah yang membawa kamu pada status baru.",
  ui_story_5067_50670801_23_dialog_content = "Aku... Kamu benar. Teman-temanku, dan penduduk kota... Mereka lah yang membuatku seperti ini.",
  ui_story_5067_50670801_24_dialog_content = "Dan tentu saja ada kamu, White Dolphin... Tanpamu, aku...",
  ui_story_5067_50670801_25_dialog_content = "Tidak perlu mengatakan itu. Seperti yang sudah saya katakan berkali-kali, pertumbuhanmu itu semua berkat kerja kerasmu sendiri.",
  ui_story_5067_50670801_26_dialog_content = "Kamu bukan lagi gadis kecil yang dulu sering panik, jadi tolong lebih percaya diri.",
  ui_story_5067_50670801_27_dialog_content = "Kekuatanmu bukan untuk disembunyikan lagi, melainkan untuk membawa musik, keberanian, dan cinta ke hati orang lain.",
  ui_story_5067_50670801_28_dialog_content = "Bisa... Bisakah aku benar-benar memiliki sesuatu yang begitu indah?",
  ui_story_5067_50670801_29_dialog_content = "Kamu selalu punya kekuatan ini, Connolly. Bahkan, ini adalah ciri khas terpentingmu.",
  ui_story_5067_50670801_30_dialog_content = "Nah, saatnya untuk kamu bangun dari mimpi ini.",
  ui_story_5067_50670801_31_dialog_content = "Namun…",
  ui_story_5067_50670801_32_dialog_content = "Kau siap?",
  ui_story_5067_50670801_33_dialog_content = "Aku…",
  ui_story_5067_50670801_34_dialog_content = "Iya, sebentar lagi.",
  ui_story_5067_50670801_35_dialog_content = "Di dunia nyata, mungkin saja aku ragu atau menghindar dari sesuatu kadang-kadang...",
  ui_story_5067_50670801_36_dialog_content = "Tapi sebagai teman-temanku... Kalian akan selalu ada untuk mengingatkan siapa diriku, kan?",
  ui_story_5067_50670801_37_dialog_content = "Tentu saja!",
  ui_story_5067_50670801_38_dialog_content = "Aku akan datang menemuimu di Holiday Cafe suatu hari nanti, jadi pastikan untuk menyiapkan secangkir kopi terbaikmu untukku saat hari itu tiba.",
  ui_story_5067_50670801_39_dialog_content = "Janji!"
}
return config
